package io.github.lu1j.rolloutcore.server.evaluation;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.CsvSource;
import io.github.lu1j.rolloutcore.server.service.BusinessException;
import java.util.Locale;
import static org.junit.jupiter.api.Assertions.*;

class StableBucketServiceTest {
    private final StableBucketService buckets = new StableBucketService();

    // Independently calculated using .NET SHA256, not generated by the implementation under test.
    @ParameterizedTest
    @CsvSource({"shop,prod,pay,user-123,2750", "checkout-service,prod,new-payment-flow,user-123,4086",
            "shop,test,pay,用户-一,48"})
    void goldenVectors(String project, String environment, String flag, String user, int expected) {
        assertEquals(expected, buckets.bucket(project, environment, flag, user));
        assertEquals(expected, new StableBucketService().bucket(project, environment, flag, user));
    }

    @Test void deterministicDistributionAndRange() {
        int hits = 0;
        for (int i = 1; i <= 50000; i++) {
            int bucket = buckets.bucket("shop", "prod", "pay", String.format(Locale.ROOT, "user-%06d", i));
            assertTrue(bucket >= 0 && bucket < 10000);
            if (bucket < 1000) hits++;
        }
        assertTrue(hits >= 4500 && hits <= 5500, "10% allocation hits: " + hits);
        System.out.println("ROLLOUT_DISTRIBUTION hits=" + hits + "/50000");
    }

    @Test void repeatedInputAndUnambiguousSeparators() {
        for (int i = 0; i < 100; i++) assertEquals(2750, buckets.bucket("shop", "prod", "pay", "user-123"));
        assertNotEquals(buckets.bucket("ab", "c", "pay", "u"), buckets.bucket("a", "bc", "pay", "u"));
        assertThrows(BusinessException.class, () -> buckets.bucket("shop", "prod", "pay", "u\0x"));
    }
}
